  function diagLog(line) {
    const { log } = diagEls();
    if (!log) {
      return;
    }
    const time = new Date().toISOString().slice(11, 23);
    log.textContent += `[${time}] ${line}\n`;
    log.scrollTop = log.scrollHeight;
  }

