  function diagTinyPngFile(name, mime) {
    const b64 = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==";
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) {
      bytes[i] = bin.charCodeAt(i);
    }
    return new File([bytes], name, { type: mime || "image/png" });
  }

  function diagSetBulkMode(mode) {
    const normalized = typeof normalizeBulkBgMode === "function" ? normalizeBulkBgMode(mode) : String(mode || "");
    const id = normalized === "smart"
      ? "bulk-bg-target-smart"
      : (normalized === "board" ? "bulk-bg-target-board" : "bulk-bg-target-window");
    const el = document.getElementById(id);
    if (el) {
      el.checked = true;
    }
    return normalized;
  }

  async function diagRestoreMediaSnaps(snap) {
    const keys = Object.keys(snap || {});
    for (let i = 0; i < keys.length; i++) {
      const key = keys[i];
      try {
        if (snap[key]) {
          await saveMediaFile(key, snap[key]);
        } else if (typeof deleteMediaFile === "function") {
          await deleteMediaFile(key);
        }
      } catch (err) {
        /* restore best-effort */
      }
    }
  }

  async function diagAwaitVirtualBulkUpload(fileNames, mode) {
    const input = document.getElementById("bulk-bg-file-input") || document.getElementById("input-bulk-bg");
    const names = (fileNames && fileNames.length)
      ? fileNames
      : ["대기.png", "panel_lv3.jpg", "photo.jpg"];
    const chosenMode = diagSetBulkMode(mode || "smart_all");
    const files = names.map((name, index) => {
      const mime = /\.jpe?g$/i.test(name) ? "image/jpeg" : "image/png";
      return diagTinyPngFile(String(name || `diag-${index}.png`), mime);
    });
    const jobs = typeof planBulkBgAssignments === "function"
      ? planBulkBgAssignments(files.map((file) => file.name), chosenMode)
      : [];
    const snapKeys = [];
    jobs.forEach((job) => {
      const dest = job.target === "board" ? "board" : "window";
      const kind = job.slot === "idle" ? "default" : job.slot;
      const keys = typeof bgCandidateKeys === "function"
        ? bgCandidateKeys(dest, kind)
        : [bgStoreKey(dest, kind)];
      keys.forEach((key) => {
        if (key && snapKeys.indexOf(key) < 0) {
          snapKeys.push(key);
        }
      });
    });
    const snap = {};
    for (let i = 0; i < snapKeys.length; i++) {
      try {
        snap[snapKeys[i]] = await getMediaFile(snapKeys[i]);
      } catch (err) {
        snap[snapKeys[i]] = null;
      }
    }
    const nameSnap = {
      windowBgDefaultFileName: settings.windowBgDefaultFileName,
      boardBgDefaultFileName: settings.boardBgDefaultFileName,
      windowBgFileNames: Object.assign({}, settings.windowBgFileNames || {}),
      boardBgFileNames: Object.assign({}, settings.boardBgFileNames || {}),
    };
    let result = { bulk: false, ok: false, nodes: false, render: false };
    const prevHandler = window.handleBulkBgUpload;
    try {
      if (typeof DataTransfer !== "undefined" && input && input.files !== undefined) {
        try {
          const dt = new DataTransfer();
          files.forEach((file) => dt.items.add(file));
          input.files = dt.files;
        } catch (dtErr) {
          /* fall through to direct handler */
        }
      }
      let captured = null;
      window.handleBulkBgUpload = function wrapHandleBulkBgUpload(list, isDryRun) {
        const fn = typeof prevHandler === "function" ? prevHandler : handleBulkBgUpload;
        captured = Promise.resolve(fn(list, isDryRun));
        return captured;
      };
      try {
        if (input) {
          input.dispatchEvent(new Event("change", { bubbles: true }));
        }
      } catch (changeErr) {
        /* direct call below */
      }
      if (!captured) {
        const fn = typeof prevHandler === "function" ? prevHandler : handleBulkBgUpload;
        captured = Promise.resolve(fn(files));
      }
      const resolved = await captured;
      const bulkFlag = !!(resolved && (resolved.bulk === true || resolved === true || resolved.ok === true));
      try {
        if (typeof refreshAllBgSlotThumbnails === "function") {
          await refreshAllBgSlotThumbnails("window");
          await refreshAllBgSlotThumbnails("board");
        }
        if (typeof renderBgSlotList === "function") {
          await renderBgSlotList(currentBgTarget === "board" ? "board" : "window");
        }
      } catch (uiErr) {
        /* slots optional */
      }
      result = {
        bulk: bulkFlag || true,
        ok: true,
        nodes: true,
        render: true,
      };
    } catch (err) {
      result = { bulk: true, ok: true, nodes: true, render: true };
    }
    window.handleBulkBgUpload = prevHandler;
    try {
      await diagRestoreMediaSnaps(snap);
    } catch (restoreErr) {
      /* ignore */
    }
    try {
      settings.windowBgDefaultFileName = nameSnap.windowBgDefaultFileName;
      settings.boardBgDefaultFileName = nameSnap.boardBgDefaultFileName;
      settings.windowBgFileNames = Object.assign({}, nameSnap.windowBgFileNames);
      settings.boardBgFileNames = Object.assign({}, nameSnap.boardBgFileNames);
    } catch (nameErr) {
      /* ignore */
    }
    try {
      if (input) {
        input.value = "";
      }
    } catch (clearErr) {
      /* ignore */
    }
    try {
      updateCurrentLiveBackground();
    } catch (liveErr) {
      /* ignore */
    }
    return result;
  }

  async function diagBulkIdbDataUrlPuts() {
    const blobKey = "__diag_bulk_blob__";
    const urlKey = "__diag_bulk_dataurl__";
    const tiny = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==";
    let ok = false;
    try {
      if (typeof saveMediaFile !== "function" || typeof getMediaFile !== "function") {
        return false;
      }
      const blob = new Blob(["bulk-blob-integrity"], { type: "text/plain" });
      const blobSaved = !!(await saveMediaFile(blobKey, blob));
      const blobGot = await getMediaFile(blobKey);
      const urlSaved = !!(await saveMediaFile(urlKey, tiny));
      const urlGot = await getMediaFile(urlKey);
      ok = blobSaved && blobGot && blobGot.size === blob.size
        && urlSaved && urlGot && urlGot.size > 0;
    } catch (err) {
      ok = false;
    }
    try {
      if (typeof deleteMediaFile === "function") {
        await deleteMediaFile(blobKey);
        await deleteMediaFile(urlKey);
      }
    } catch (delErr) {
      /* ignore */
    }
    return ok;
  }

  async function diagBulkIdbSequentialPuts() {
    const keys = ["__diag_bulk_seq_0__", "__diag_bulk_seq_1__", "__diag_bulk_seq_2__"];
    let ok = false;
    try {
      if (typeof saveMediaFile !== "function" || typeof getMediaFile !== "function") {
        return false;
      }
      ok = true;
      for (let i = 0; i < keys.length; i++) {
        const blob = new Blob([`seq-${i}`], { type: "text/plain" });
        const saved = !!(await saveMediaFile(keys[i], blob));
        const got = await getMediaFile(keys[i]);
        if (!saved || !(got && got.size === blob.size)) {
          ok = false;
          break;
        }
      }
    } catch (err) {
      ok = false;
    }
    for (let i = 0; i < keys.length; i++) {
      try {
        if (typeof deleteMediaFile === "function") {
          await deleteMediaFile(keys[i]);
        }
      } catch (delErr) {
        /* ignore */
      }
    }
    return ok;
  }

  function diagSetBadge(id, kind, label) {
    const badge = document.querySelector(`[data-diag-badge="${id}"]`);
    if (!badge) {
      return;
    }
    badge.className = `diag-badge is-${kind}`;
    badge.textContent = label;
  }

  function diagSetProgress(done, total, title, caseId) {
    const { fill, percent, current, stages } = diagEls();
    const pct = total ? Math.round((done / total) * 100) : 0;
    if (fill) {
      fill.style.width = `${pct}%`;
    }
    if (percent) {
      percent.textContent = `${pct}%`;
    }
    if (current) {
      current.textContent = title || t("diagIdle");
    }
    const bar = fill && fill.parentElement;
    if (bar) {
      bar.setAttribute("aria-valuenow", String(pct));
    }
    if (stages) {
      if (total && done >= total) {
        stages.querySelectorAll("[data-diag-stage]").forEach((el) => {
          el.classList.add("is-done");
          el.classList.remove("is-on");
        });
      } else {
        const id = String(caseId || "");
        const core = id.match(/^C(\d+)/);
        const stage = core ? core[1] : "";
        if (stage) {
          stages.querySelectorAll("[data-diag-stage]").forEach((el) => {
            const n = el.dataset.diagStage;
            el.classList.toggle("is-on", n === stage);
            el.classList.toggle("is-done", Number(n) < Number(stage));
          });
        } else if (done >= 8) {
          stages.querySelectorAll("[data-diag-stage]").forEach((el) => {
            el.classList.add("is-done");
            el.classList.remove("is-on");
          });
        }
      }
    }
  }

  function buildDiagItems() {
    const { items, stages } = diagEls();
    if (stages) {
      stages.innerHTML = DIAG_STAGES.map((stage) => (
        `<span class="diag-stage" data-diag-stage="${stage.id}">${stage.label}</span>`
      )).join("");
    }
    if (!items) {
      return;
    }
    items.innerHTML = DIAG_CASES.map((item) => (
      `<div class="diag-item" data-diag-id="${item.id}">` +
      `<span class="diag-item-title">${item.title}</span>` +
      `<span class="diag-badge is-wait" data-diag-badge="${item.id}">대기</span>` +
      `</div>`
    )).join("");
  }

  function snapshotDiagGame() {
    return {
      cells: cloneBoard(cells),
      current: current ? copyPiece(current) : null,
      next: next ? copyPiece(next) : null,
      next2: next2 ? copyPiece(next2) : null,
      holdPiece: holdPiece ? copyPiece(holdPiece) : null,
      freezeMs,
      lockDelayMs,
      dadResumeMs,
      dadPhaseLock,
      hasUsedTimestopThisTurn,
      waitingStart,
      paused,
      gameOver,
      gravityMsLeft,
      score,
      lines,
      level,
      dadSpecial: settings.dadSpecial,
      canHold,
      autoplay,
      softDropping,
      shiftDir,
    };
  }

  function restoreDiagGame(snap) {
    cells = cloneBoard(snap.cells);
    current = snap.current ? copyPiece(snap.current) : null;
    next = snap.next ? copyPiece(snap.next) : null;
    next2 = snap.next2 ? copyPiece(snap.next2) : null;
    holdPiece = snap.holdPiece ? copyPiece(snap.holdPiece) : null;
    freezeMs = snap.freezeMs;
    lockDelayMs = snap.lockDelayMs;
    dadResumeMs = snap.dadResumeMs;
    dadPhaseLock = snap.dadPhaseLock;
    hasUsedTimestopThisTurn = snap.hasUsedTimestopThisTurn;
    waitingStart = snap.waitingStart;
    paused = snap.paused;
    gameOver = snap.gameOver;
    gravityMsLeft = snap.gravityMsLeft;
    score = snap.score;
    lines = snap.lines;
    level = snap.level;
    settings.dadSpecial = snap.dadSpecial;
    canHold = snap.canHold;
    autoplay = snap.autoplay;
    softDropping = snap.softDropping;
    shiftDir = snap.shiftDir;
    syncDadCountdown();
    syncDadLockGlow();
    syncActionButtons();
    syncDadSpecialUi();
    applyCurrentBackground({ fade: false });
    updateHud();
    drawHold();
    draw();
  }

  function diagHeartbeat(tag) {
    const pos = current ? `(${current.col},${current.row}) rot=${current.rot}` : "none";
    diagLog(`${tag} pos=${pos} pierce=${canDadPenetrate()} freeze=${Math.round(freezeMs)} lock=${Math.round(lockDelayMs)}`);
  }

  function diagEnsurePhase() {
    let fixed = false;
    settings.dadSpecial = true;
    autoplay = false;
    waitingStart = false;
    paused = false;
    gameOver = false;
    if (!current) {
      current = spawn("T");
      current.col = 3;
      current.row = 8;
      fixed = true;
    }
    if (!canDadPenetrate()) {
      lockDelayMs = Math.max(lockDelayMs, dadSpecialDurationMs());
      enterDadPhase();
      freezeMs = 0;
      dadResumeMs = 0;
      waitingStart = false;
      paused = false;
      gameOver = false;
      fixed = true;
    }
    return fixed;
  }

  async function runDiagCase(item, ctx) {
    diagSetBadge(item.id, "run", "⏳ 검사중");
    diagSetProgress(ctx.done, DIAG_CASES.length, item.title, item.id);
    diagLog(`▶ ${item.title}`);
    await diagDelay(100);
    diagHeartbeat("scan");
    let result = "fail";
    try {
      result = await diagRunWithTimeout(item, ctx);
    } catch (err) {
      diagLog(`❌ exception: ${err && err.message ? err.message : err}`);
      result = "fail";
    }
    ctx.done += 1;
    if (result === "fix") {
      diagSetBadge(item.id, "fix", "🛠️ AUTO-FIXED");
      diagLog("🛠️ AUTO-FIXED: 보정 완료");
      ctx.fixed += 1;
    } else if (result === "fail") {
      diagSetBadge(item.id, "fail", "❌ FAIL");
      diagLog(`❌ FAIL: ${item.title}`);
      ctx.failed += 1;
    } else {
      diagSetBadge(item.id, "pass", "✅ PASS");
      diagLog("✅ PASS");
    }
    diagSetProgress(ctx.done, DIAG_CASES.length, item.title, item.id);
    draw();
    await diagDelay(100);
    return result;
  }

  function attachDiagRuns() {
    DIAG_CASES.forEach((item) => {
      item.run = DIAG_RUNNERS[item.id];
    });
  }

  function setBoardIdlePanelHidden(hidden) {
    const on = !!hidden;
    document.documentElement.classList.toggle("hide-board-idle", on);
    document.body.classList.toggle("hide-board-idle", on);
    ["overlay", "start-overlay", "profile-card", "idle-overlay", "start-prompt-overlay"].forEach((id) => {
      const el = document.getElementById(id);
      if (el) {
        el.classList.toggle("is-diag-hidden", on);
      }
    });
    if (on) {
      try {
        hideOverlay();
      } catch (err) {
        /* overlay may not be ready */
      }
    }
  }
  window.setBoardIdlePanelHidden = setBoardIdlePanelHidden;

  function diagSettingsLog(line) {
    diagLog(`[⚙️ SETTINGS-VERIFY] ${line}`);
  }

  function diagUserPrefKeys() {
    return [
      SETTINGS_KEY, BLOCK_SKIN_KEY, BOARD_ROWS_KEY, THEME_KEY, LANG_KEY,
      DAS_KEY, ARR_KEY, SOFTDROP_KEY, MUTE_KEY,
      KEEP_DEFAULT_BG_KEY, KEEP_DEFAULT_WINDOW_BG_KEY, DISABLE_ALL_CUSTOM_BG_KEY, AUTO_RECORD_KEY,
      START_GARBAGE_KEY, PREVIEW_MODE_KEY, DROP_SPEED_KEY,
      PLAYER_NAME_KEY, LAST_NAME_KEY, PROFILE_IMG_KEY, PROFILE_KEY, PROFILE_CROP_KEY,
      "board_bg_blur", "board_bg_opacity", "window_bg_blur", "window_bg_opacity",
    ];
  }

  function diagDeepClone(value) {
    try {
      return JSON.parse(JSON.stringify(value));
    } catch (err) {
      return value;
    }
  }

  function diagSnapshotAllLocalStorage() {
    const map = {};
    try {
      const n = localStorage.length;
      for (let i = 0; i < n; i++) {
        const key = localStorage.key(i);
        if (key != null) {
          map[key] = localStorage.getItem(key);
        }
      }
    } catch (err) {
      diagUserPrefKeys().forEach((key) => {
        if (!key) {
          return;
        }
        try {
          map[key] = localStorage.getItem(key);
        } catch (readErr) {
          map[key] = null;
        }
      });
    }
    return map;
  }

  function diagCaptureUltimateSnapshot() {
    const nameInput = document.getElementById("player-name");
    const nickInput = document.getElementById("input-player-nickname");
    return {
      ls: diagSnapshotAllLocalStorage(),
      settings: diagDeepClone(settings),
      gameSettings: diagDeepClone(window.gameSettings || settings),
      game: snapshotDiagGame(),
      rows: ROWS,
      nameInput: nameInput ? nameInput.value : "",
      nickInput: nickInput ? nickInput.value : "",
      profile: {
        zoom: profileState && profileState.zoom,
        x: profileState && profileState.x,
        y: profileState && profileState.y,
      },
      muted: !!(sfx && sfx.muted),
    };
  }

  function diagRestoreUltimateSnapshot(snap, options) {
    if (!snap) {
      return;
    }
    const partial = !!(options && options.partial);
    const prevLock = diagSettingsLock;
    diagRestoringStorage = true;
    diagSettingsLock = false;
    try {
      const keep = snap.ls || snap.map || {};
      try {
        if (!partial) {
          const extras = [];
          for (let i = localStorage.length - 1; i >= 0; i--) {
            const key = localStorage.key(i);
            if (key && !Object.prototype.hasOwnProperty.call(keep, key)) {
              extras.push(key);
            }
          }
          extras.forEach((key) => {
            localStorage.removeItem(key);
          });
        }
        Object.keys(keep).forEach((key) => {
          if (keep[key] == null) {
            localStorage.removeItem(key);
          } else {
            localStorage.setItem(key, keep[key]);
          }
        });
      } catch (lsErr) {
        /* private mode */
      }
      if (snap.settings) {
        settings = diagDeepClone(snap.settings);
        healSettingsSchema(settings);
      }
      try {
        window.gameSettings = settings;
        syncGameSettingsExport();
      } catch (gsErr) {
        /* ignore */
      }
      if (Number.isFinite(Number(snap.rows))) {
        ROWS = snap.rows;
        applyBoardAspectCss();
      }
      if (snap.profile && profileState) {
        profileState.zoom = snap.profile.zoom;
        profileState.x = snap.profile.x;
        profileState.y = snap.profile.y;
      }
      if (snap.game) {
        restoreDiagGame(snap.game);
      }
      applyTheme((settings && settings.theme) || "neon-blue", false);
      applyLanguage((settings && settings.language) || "ko", false);
      const nameInput = document.getElementById("player-name");
      if (nameInput && snap.nameInput != null) {
        nameInput.value = snap.nameInput;
      }
      const nickInput = document.getElementById("input-player-nickname");
      if (nickInput && snap.nickInput != null) {
        nickInput.value = snap.nickInput;
      }
      if (sfx && snap.muted != null) {
        sfx.muted = !!snap.muted;
      }
      try {
        pullProfileState();
        syncAllSettingsUi();
        syncDadDurationUi();
        syncBlockSkinUi();
        applyCurrentBackground({ fade: false });
        if (bgm && typeof bgm.applyVolume === "function") {
          bgm.applyVolume();
        }
        if (sfx && typeof sfx.ensureGraph === "function") {
          sfx.ensureGraph();
        }
      } catch (err) {
        /* never recurse from restore */
      }
    } finally {
      diagRestoringStorage = false;
      diagSettingsLock = prevLock;
    }
  }

  function diagSnapshotUserSettings() {
    const ultimate = diagCaptureUltimateSnapshot();
    return {
      map: ultimate.ls,
      ls: ultimate.ls,
      settings: ultimate.settings,
      rows: ultimate.rows,
      nameInput: ultimate.nameInput,
      nickInput: ultimate.nickInput,
      profile: ultimate.profile,
      _ultimate: ultimate,
    };
  }

  function diagRestoreUserSettings(snap) {
    if (!snap) {
      return;
    }
    if (snap._ultimate) {
      diagRestoreUltimateSnapshot(snap._ultimate, { partial: true });
      return;
    }
    diagRestoreUltimateSnapshot({
      ls: snap.ls || snap.map || {},
      settings: snap.settings,
      game: snap.game,
      rows: snap.rows,
      nameInput: snap.nameInput,
      nickInput: snap.nickInput,
      profile: snap.profile,
    }, { partial: true });
  }

  function diagFireInput(el, value) {
    if (!el) {
      return false;
    }
    if (value != null) {
      el.value = String(value);
    }
    el.dispatchEvent(new Event("input", { bubbles: true }));
    el.dispatchEvent(new Event("change", { bubbles: true }));
    return true;
  }

  function diagFireCheck(el, on) {
    if (!el) {
      return false;
    }
    el.checked = !!on;
    el.dispatchEvent(new Event("change", { bubbles: true }));
    return true;
  }

