  function safeSfxEnsure() {
    try {
      if (sfx && typeof sfx.ensure === "function") {
        sfx.ensure();
      }
    } catch (err) {
      /* audio optional */
    }
  }

  function onHudStartGame() {
    if (gameTerminated) {
      return;
    }
    try {
      safeSfxEnsure();
    } catch (sfxErr) {
      /* audio optional */
    }
    try {
      if (waitingStart || gameOver || !current) {
        try { stopAutoplay(); } catch (apErr) {}
        startNewGame();
        return;
      }
      togglePause();
    } catch (err) {
      try {
        startNewGame();
      } catch (err2) {
        try {
          waitingStart = false;
          paused = false;
          gameOver = false;
          cells = Array.from({ length: ROWS || 20 }, () => Array(COLS || 10).fill(0));
          if (!loopRaf) {
            loopRaf = requestAnimationFrame(loop);
          }
        } catch (err3) {
          /* last resort */
        }
      }
    }
  }

  function onHudEndGame() {
    if (gameTerminated) {
      return;
    }
    if (gameOver) {
      quitGameApp();
      return;
    }
    safeSfxEnsure();
    try {
      stopAutoplay();
    } catch (err) {
      /* ignore */
    }
    endGame();
  }

