  async function initApp() {
    if (window.__dadInitAppStarted) {
      return;
    }
    window.__dadInitAppStarted = true;
    window.__dadBootOrder = { lsLoaded: false, idbReady: false, hydrated: false, painted: false };
    try {
      loadLocalStorageSettings();
      window.__dadBootOrder.lsLoaded = true;
    } catch (bootUiErr) {
      try {
        syncAllSettingsUi();
      } catch (syncErr) {
        /* keep boot alive */
      }
      window.__dadBootOrder.lsLoaded = true;
    }
    try {
      if (window.MediaStorage && typeof window.MediaStorage.initDB === "function") {
        await window.MediaStorage.initDB();
      } else {
        await initIndexedDB();
      }
      window.__dadBootOrder.idbReady = true;
    } catch (idbErr) {
      try {
        await initIndexedDB();
      } catch (idbErr2) {
        /* continue with bundled assets */
      }
      window.__dadBootOrder.idbReady = true;
    }
    try {
      await hydrateMedia();
      window.__dadBootOrder.hydrated = true;
    } catch (bootMediaErr) {
      try {
        applyBundledBgm();
      } catch (bgmErr) {
        /* ignore */
      }
      window.__dadBootOrder.hydrated = true;
    }
    try {
      applyAllSettings();
    } catch (applyErr) {
      try {
        loadAndApplyCurrentBackground({ fade: false });
      } catch (bgErr) {
        /* bundled paint optional */
      }
    }
    try {
      await updateLevelBackground(playLevel(level) || 1, { fade: false, force: true, allowClear: false });
      await updateBoardBackground(playLevel(level) || 1, { fade: false, force: true, allowClear: false });
    } catch (lvBgErr) {
      /* idle/custom already applied */
    }
    renderInitialScreen();
    window.__dadBootOrder = window.__dadBootOrder || {};
    window.__dadBootOrder.painted = true;
  }
  window.loadLocalStorageSettings = loadLocalStorageSettings;
  window.renderInitialScreen = renderInitialScreen;
  window.initApp = initApp;
